-- Phong Than 2026-10-04 (agent vtcc): VNG drops of the Van Tien tran tien, Thong Thien and Bao ruong.
-- Generated by scratchpad\vtcc\gen_drop.py from settings\phongthan\Npcs.txt (Treasure / DropRateFile pairs) and
-- the VNG \settings\item\droprate\*.ini; only entries that exist on server AND client are kept (drop_report.txt).
-- The engine does not read DropRateFile, so the ActionScripts vt_boss.lua / vt_chest.lua call PTVD_Drop(npc):
-- n rolls per table (n = Treasure for DropRateFile, Treasure1 for DropRateFile1), each roll random(1, RandRange)
-- against the cumulative RandRate; equipment / potion level weighted between MinItemLevel(Scale) and
-- MaxItemLevel(Scale). Items go into the killer's bag (AddNormalItemPile: stacks, nothing on the ground); the
-- special table (DropRateFile1) is given first, a full bag stops the rest. Genre-7 VNG skill books are given as
-- the project's usable bi kip 6/1/(62000 + skill) when that row exists. Do not edit: run the generator.
-- 0 = VNG (the tien roll their special table DropRateFile1 = jiuying.ini Treasure1 = 0 times: no bi kip).
-- n > 0 = non-VNG option: the tien roll that table n times (bi kip he phai, do luc 0/2/3-5, 0/9/3-5, Minh Uyen).
PTVD_FORCE1 = 1   -- 2026-10-04 user choice (not VNG): every tien rolls jiuying.ini once (bi kip, do luc)
PTVD_T = {}
PTVD_N = {}
PTVD_C = { {}, {}, {} }
PTVD_TTLV = {}

function PTVD_Tab(k, range)
	local t = {}
	t.range = range
	t.n = 0
	PTVD_T[k] = t
end

-- one entry: genre, detail, particular, rate, name; levels added by PTVD_Lv
function PTVD_Ent(k, g, d, p, r, nm)
	local t = PTVD_T[k]
	local e = {}
	e.g = g
	e.d = d
	e.p = p
	e.r = r
	e.nm = nm
	e.lv = {}
	e.lw = 0
	e.pri = 0
	if g == 0 and d ~= 4 and p <= 3 then e.pri = 1 end   -- plain white gear of the generic boss table: given last
	t.n = t.n + 1
	t[t.n] = e
end

function PTVD_Lv(k, lv, wt)
	local t = PTVD_T[k]
	local e = t[t.n]
	tinsert(e.lv, { lv, wt })
	e.lw = e.lw + wt
end

-- entry of table k (last added) belongs to bonus category cat (profession prof, -1 = any)
function PTVD_Cat(k, cat, prof)
	local t = PTVD_T[k]
	local e = t[t.n]
	e.prof = prof
	tinsert(PTVD_C[cat], e)
end

-- template: rolls of the main table, its key, rolls of the special table, its key
function PTVD_Npc(tpl, n0, k0, n1, k1)
	local o = {}
	o.n0 = n0
	o.k0 = k0
	o.n1 = n1
	o.k1 = k1
	PTVD_N[tpl] = o
end

