-- level of entry e (weighted)
function PTVD_PickLv(e)
	local n = getn(e.lv)
	if n <= 1 then return e.lv[1][1] end
	local r = random(1, e.lw)
	local i = 1
	while i <= n do
		r = r - e.lv[i][2]
		if r <= 0 then return e.lv[i][1] end
		i = i + 1
	end
	return e.lv[n][1]
end

-- n rolls of table k: picked entries appended to out
function PTVD_Roll(k, n, out)
	local t = PTVD_T[k]
	if not t or n <= 0 then return end
	local j = 1
	while j <= n do
		local r = random(1, t.range)
		local i = 1
		while i <= t.n do
			r = r - t[i].r
			if r <= 0 then
				tinsert(out, t[i])
				i = t.n
			end
			i = i + 1
		end
		j = j + 1
	end
end

-- weighted pick in bonus category cat (prof >= 0: only entries of that profession or any); nil if empty
function PTVD_PickCat(cat, prof)
	local c = PTVD_C[cat]
	local sum = 0
	local i = 1
	while c[i] do
		if prof < 0 or c[i].prof < 0 or c[i].prof == prof then sum = sum + c[i].r end
		i = i + 1
	end
	if sum <= 0 then return nil end
	local r = random(1, sum)
	i = 1
	while c[i] do
		if prof < 0 or c[i].prof < 0 or c[i].prof == prof then
			r = r - c[i].r
			if r <= 0 then return c[i] end
		end
		i = i + 1
	end
	return nil
end

-- guaranteed Thong Thien bonus (PTVD_FORCE1 > 0): PTVD_TTB[1] bi kip of the killer's profession, [2] phap bao,
-- [3] do luc pieces, at the tran level PTVD_TTLV (7 Tho .. 10 Phong, highest level of the entry otherwise)
function PTVD_Bonus(tpl, out)
	local lv = PTVD_TTLV[tpl]
	if not lv or PTVD_FORCE1 <= 0 then return end
	local prof = GetPlayerType()
	if not prof or prof < 0 or prof > 2 then prof = -1 end
	local cat = 1
	while cat <= 3 do
		local n = 0
		while n < PTVD_TTB[cat] do
			local e = PTVD_PickCat(cat, prof)
			if not e and cat == 1 then e = PTVD_PickCat(cat, -1) end
			if e then
				local b = {}
				b.g = e.g
				b.d = e.d
				b.p = e.p
				b.nm = e.nm
				b.pri = -1
				b.lv = { { lv, 1 } }
				b.lw = 1
				if not PTVD_HasLv(e, lv) then
					b.lv = e.lv
					b.lw = e.lw
				end
				tinsert(out, b)
			end
			n = n + 1
		end
		cat = cat + 1
	end
end

function PTVD_HasLv(e, lv)
	local i = 1
	while e.lv[i] do
		if e.lv[i][1] == lv then return 1 end
		i = i + 1
	end
	return nil
end

-- create one item in the current player's bag; 1 = given, 0 = no room (nothing is dropped on the ground)
function PTVD_GiveOne(e)
	local lv = PTVD_PickLv(e)
	local se = 0
	if e.g == 0 then se = random(0, 4) end
	local r = AddNormalItemPile(e.g, e.d, e.p, lv, se, 0)
	if r and r > 0 then return 1 end
	return 0
end

-- VNG drop of NPC ni for the current player (the killer); returns given, lost
function PTVD_Drop(ni)
	local o = PTVD_N[GetNpcTemplateID(ni)]
	if not o or not AddNormalItemPile then return 0, 0 end
	local list = {}
	local n1 = o.n1
	if n1 == 0 and PTVD_FORCE1 > 0 and o.k1 > 0 then n1 = PTVD_FORCE1 end
	PTVD_Bonus(GetNpcTemplateID(ni), list)
	PTVD_Roll(o.k1, n1, list)
	PTVD_Roll(o.k0, o.n0, list)
	local got = 0
	local lost = 0
	local names = ""
	local pass = -1
	while pass <= 1 do
		local i = 1
		while list[i] do
			if list[i].pri == pass then
				if lost == 0 and PTVD_GiveOne(list[i]) == 1 then
					got = got + 1
					if got <= 6 then names = names .. ", " .. list[i].nm end
				else
					lost = lost + 1
				end
			end
			i = i + 1
		end
		pass = pass + 1
	end
	if got > 0 then
		local s = "V\203t ph\200m r\172i (b\182ng VNG): nh\203n " .. got .. " m\227n: " .. strsub(names, 3)
		if got > 6 then s = s .. "..." end
		Msg2Player(s .. ".")
	end
	if lost > 0 then Msg2Player("H\181nh trang \174\199y: " .. lost .. " v\203t ph\200m r\172i kh\171ng nh\203n \174\173\238c. H\183y d\228n b\237t h\181nh trang.") end
	return got, lost
end
